class Solution {
public:
    long long findTheArrayConcVal(vector<int>& nums) {
        long long ans = 0;
        int l = 0, r = nums.size() - 1;
        while (l < r) {
            long long p = 10, b = nums[r];
            while (p <= b) p *= 10;
            ans += nums[l] * p + b;
            l++; r--;
        }
        if (l == r) ans += nums[l];
        return ans;
    }
};

